 hist=mask.histogram();return {'sameDecodedRGBA':a.tobytes()==b.tobytes(),'size':list(a.size),'changedPixels':sum(hist[1:]),'maximumAbsoluteChannelResidual':[c.getextrema()[1] for c in bands],'differenceBounds':mask.getbbox()}
