 comparisons[d]={'wholeNativeBOXvsPublished':compare(p,n.resize((384,704),Image.Resampling.BOX)),'publishedVsAtlas':compare(p,a),'savedSourceReplayNative':compare(n,r),'savedSourceReplayPublishedBOX':compare(p,r.resize((384,704),Image.Resampling.BOX)),'savedSourceReplayStrip':compare(strip,rs)}
 assert comparisons[d]['wholeNativeBOXvsPublished']['sameDecodedRGBA'] and comparisons[d]['publishedVsAtlas']['sameDecodedRGBA']
